use super::port::parse_port;

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Url {
    scheme: String,
    authority: String,
    port: i32,
    path: String,
    query: String,
    fragment: String,
    valid: bool,
}

impl Url {
    pub fn new(input: &str) -> Self {
        let (scheme, authority_raw, tail) = split_scheme_and_authority(input);
        let (authority, port, host) = normalize_authority(authority_raw);
        let (path, query, fragment) = split_tail(tail);
        let valid = !host.is_empty() || !path.is_empty();

        Self {
            scheme,
            authority,
            port,
            path,
            query,
            fragment,
            valid,
        }
    }

    pub fn scheme(&self) -> &str {
        &self.scheme
    }

    pub fn authority(&self) -> &str {
        &self.authority
    }

    pub fn port(&self) -> i32 {
        self.port
    }

    pub fn path(&self) -> &str {
        &self.path
    }

    pub fn query(&self) -> &str {
        &self.query
    }

    pub fn fragment(&self) -> &str {
        &self.fragment
    }

    pub fn is_valid(&self) -> bool {
        self.valid
    }
}

fn split_scheme_and_authority(input: &str) -> (String, &str, &str) {
    if let Some(scheme_end) = input.find("://") {
        let scheme = input[..scheme_end].to_ascii_lowercase();
        let rest = &input[scheme_end + 3..];

        if let Some(authority_end) = rest.find(['/', '?', '#']) {
            let authority = &rest[..authority_end];
            let tail = &rest[authority_end..];
            (scheme, authority, tail)
        } else {
            (scheme, rest, "")
        }
    } else {
        (String::new(), "", input)
    }
}

fn normalize_authority(authority_raw: &str) -> (String, i32, String) {
    if authority_raw.is_empty() {
        return (String::new(), -1, String::new());
    }

    if let Some(colon_index) = authority_raw.find(':') {
        let host = authority_raw[..colon_index].to_string();
        let port_text = &authority_raw[colon_index + 1..];

        if let Some(port) = parse_port(port_text) {
            (format!("{}:{}", host, port), port, host)
        } else {
            (host.clone(), -1, host)
        }
    } else {
        let host = authority_raw.to_string();
        (host.clone(), -1, host)
    }
}

fn split_tail(tail: &str) -> (String, String, String) {
    let (without_fragment, fragment) = if let Some(fragment_index) = tail.find('#') {
        (
            &tail[..fragment_index],
            tail[fragment_index + 1..].to_string(),
        )
    } else {
        (tail, String::new())
    };

    let (path, query) = if let Some(query_index) = without_fragment.find('?') {
        (
            without_fragment[..query_index].to_string(),
            without_fragment[query_index + 1..].to_string(),
        )
    } else {
        (without_fragment.to_string(), String::new())
    };

    (path, query, fragment)
}

#[cfg(test)]
mod tests {
    use super::Url;

    #[test]
    fn normalizes_scheme_and_port() {
        let url = Url::new("Http+X://Example.com:0012/path?Q#F");

        assert_eq!(url.scheme(), "http+x");
        assert_eq!(url.authority(), "Example.com:12");
        assert_eq!(url.port(), 12);
        assert_eq!(url.path(), "/path");
        assert_eq!(url.query(), "Q");
        assert_eq!(url.fragment(), "F");
        assert!(url.is_valid());
    }

    #[test]
    fn treats_missing_scheme_as_path() {
        let url = Url::new("example.com?x=1#f");

        assert_eq!(url.scheme(), "");
        assert_eq!(url.authority(), "");
        assert_eq!(url.port(), -1);
        assert_eq!(url.path(), "example.com");
        assert_eq!(url.query(), "x=1");
        assert_eq!(url.fragment(), "f");
        assert!(url.is_valid());
    }

    #[test]
    fn matches_hostless_authority_validity() {
        let url = Url::new("http://:80/path");

        assert_eq!(url.authority(), ":80");
        assert_eq!(url.port(), 80);
        assert_eq!(url.path(), "/path");
        assert!(url.is_valid());
    }
}

