use crate::parse::{parse_authority, split_authority_and_suffix, split_path_query_fragment};

pub struct Url {
    scheme: String,
    authority: String,
    port: i32,
    path: String,
    query: String,
    fragment: String,
    valid: bool,
}

impl Url {
    pub fn new(input: String) -> Self {
        match input.find("://") {
            Some(index) => {
                let scheme = input[..index].to_ascii_lowercase();
                let remainder = &input[index + 3..];
                let (authority_text, suffix) = split_authority_and_suffix(remainder);
                let authority_parts = parse_authority(authority_text);
                let path_parts = split_path_query_fragment(suffix);
                let valid = !authority_parts.host.is_empty() || !path_parts.path.is_empty();

                Self {
                    scheme,
                    authority: authority_parts.authority,
                    port: authority_parts.port,
                    path: path_parts.path,
                    query: path_parts.query,
                    fragment: path_parts.fragment,
                    valid,
                }
            }
            None => {
                let path_parts = split_path_query_fragment(&input);
                let valid = !path_parts.path.is_empty();

                Self {
                    scheme: String::new(),
                    authority: String::new(),
                    port: -1,
                    path: path_parts.path,
                    query: path_parts.query,
                    fragment: path_parts.fragment,
                    valid,
                }
            }
        }
    }

    pub fn scheme(&self) -> &str {
        &self.scheme
    }

    pub fn authority(&self) -> &str {
        &self.authority
    }

    pub fn port(&self) -> i32 {
        self.port
    }

    pub fn path(&self) -> &str {
        &self.path
    }

    pub fn query(&self) -> &str {
        &self.query
    }

    pub fn fragment(&self) -> &str {
        &self.fragment
    }

    pub fn is_valid(&self) -> bool {
        self.valid
    }
}
